INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 4, 'theory', 'Quiz: database replication');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 0, 'What do replicas scale in a leader-and-followers scheme?', '["Only writes", "Reads", "Writes and reads equally", "Disk size"]', 1, 'All writes go to the leader; replicas take over the reads.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 1, 'What does asynchronous replication risk when the leader fails?', '["Losing some confirmed writes that never reached the replicas", "Reads stopping forever", "Duplication of all the data", "Nothing"]', 0, 'The leader confirmed a write but did not manage to send it to a replica: after failover the write is lost (RPO > 0).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 2, 'How do you guarantee that a user sees their own write with asynchronous replicas?', '["Always read from the farthest replica", "After a write, read from the leader or from a replica that has applied the needed log position", "Increase the cache TTL", "Turn replication off"]', 1, 'This is the read-your-writes guarantee: for a short time read from the leader, or check the log position.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 3, 'Why is a replica not a replacement for a backup?', '["A replica is too slow", "An erroneous delete is instantly applied on the replicas too", "A replica cannot be stored in another region", "A replica encrypts the data"]', 1, 'A replica repeats all changes, including mistaken ones; you need snapshots and a log for point-in-time recovery.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 4, 'In quorum replication N = 3 and a write is confirmed by W = 2. What R is needed for a read to be guaranteed to see the latest write?', '["R = 1", "R = 2", "R = 0", "R is not needed"]', 1, 'The condition is W + R > N: 2 + 2 > 3, the sets overlap, and at least one queried node holds the fresh write.');
